   417→    /* Handle function calls: name(...) */
   418→    if (parser_match(p, TOK_LPAREN)) {
   419→        /* Get function name from expr */
   420→        if (e->kind != EXPR_VAR) {
   421→            return e;  /* not a function call */
   422→        }
   423→
   424→        const char *func_name = e->var.name;
   425→        parser_advance(p);  /* skip ( */
   426→
   427→        /* Parse arguments - dynamic array */
   428→        int arg_capacity = 32;
   429→        Expr **args = malloc(sizeof(Expr *) * arg_capacity);
   430→        int arg_count = 0;
   431→
   432→        while (!parser_match(p, TOK_RPAREN) && !parser_match(p, TOK_EOF)) {
   433→            /* Grow array if needed */
   434→            if (arg_count >= arg_capacity) {
   435→                arg_capacity *= 2;
   436→                Expr **new_args = malloc(sizeof(Expr *) * arg_capacity);
   437→                for (int i = 0; i < arg_count; i++) {
   438→                    new_args[i] = args[i];
   439→                }
   440→                free(args);
   441→                args = new_args;
   442→            }
   443→            args[arg_count++] = parse_expression(p);
   444→            if (parser_match(p, TOK_COMMA)) {
   445→                parser_advance(p);
   446→            }
   447→        }
   448→
   449→        parser_accept(p, TOK_RPAREN);
   450→
   451→        /* Free the original VAR expr */
